//! Blok 1 — block 1: onafhankelijke handhavingscontroles (CPython hashlib).
//!
//! Verwachtingen zijn onafhankelijk gegenereerd met CPython's hashlib, dus deze
//! tests lopen niet mee met een eigen interpretatie van de specificatie.

fn sha256(m: &[u8]) -> [u8; 32] {
    let mut h = <sha2::Sha256 as sha2::Digest>::new();
    sha2::Digest::update(&mut h, m);
    let out = sha2::Digest::finalize(h);
    let mut d = [0u8; 32];
    d.copy_from_slice(&out);
    d
}

